```csharp
using DocumentFormat.OpenXml.Packaging;
using DocumentFormat.OpenXml.Wordprocessing;

public void MergeWordDocuments(string sourceDoc1Path, string sourceDoc2Path, string outputDocPath)
{
    // Open the first source document
    using (WordprocessingDocument doc1 = WordprocessingDocument.Open(sourceDoc1Path, false))
    {
        // Get the main document part
        MainDocumentPart mainPart1 = doc1.MainDocumentPart;

        // Create a new document with the same settings as the first document
        using (WordprocessingDocument mergedDoc = WordprocessingDocument.Create(outputDocPath, WordprocessingDocumentType.Document))
        {
            // Add the main document part to the new document
            MainDocumentPart mainPartMerged = mergedDoc.AddMainDocumentPart();

            // Copy the content from the first document
            mainPartMerged.Document = mainPart1.Document.CloneNode(true);

            // Open the second source document
            using (WordprocessingDocument doc2 = WordprocessingDocument.Open(sourceDoc2Path, false))
            {
                // Get the main document part
                MainDocumentPart mainPart2 = doc2.MainDocumentPart;

                // Get the body of the second document
                Body body2 = mainPart2.Document.Body;

                // Get the body of the merged document
                Body bodyMerged = mainPartMerged.Document.Body;

                // Append the content from the second document's body to the merged document's body
                foreach (var element in body2.Elements())
                {
                    if (element is Paragraph || element is Run || element is Table || element is Drawing)
                    {
                        bodyMerged.Append(element.CloneNode(true));
                    }
                }

                // Save the changes to the merged document
                mainPartMerged.Document.Save();
            }
        }
    }
}
```

This code creates a new Word document (`outputDocPath`) that contains the first two pages, headers, footers, and design elements (fonts and styles) from the first source document (`sourceDoc1Path`), and then appends the content from the second source document (`sourceDoc2Path`). The resulting document will have the combined content while preserving the formatting and structure of both original documents.

