  Gl.uniform1fv ~location:(Gl.get_uniform_location ~program ~name:"a") ~values:data_a;
  Gl.uniform1fv ~location:(Gl.get_uniform_location ~program ~name:"b") ~values:data_b;
  Gl.uniform1fv ~location:(Gl.get_uniform_location ~program ~name:"c") ~values:[| 0.0; 0.0; 0.0 |];
  Gl.dispatch_compute ~group_count_x:1 ~group_count_y:1 ~group_count_z:1;
  Gl.memory_barrier ~barriers:(Gl.MemoryBarrier.ShaderStorageBufferObject)
