```java
import java.util.List;
import java.util.Optional;

public class ListChecker {

    public static <T> T checkList(List<T> list) {
        // Check if the list is empty
        if (list.isEmpty()) {
            return null;
        }

        // Use stream to count the number of elements in the list
        long count = list.stream().count();

        // If there is more than one element, throw an exception
        if (count > 1) {
            throw new IllegalStateException("List contains more than one element");
        }

        // If there is exactly one element, return it
        Optional<T> firstElement = list.stream().findFirst();
        return firstElement.orElse(null);
    }

    public static void main(String[] args) {
        List<String> exampleList = List.of("single");

        try {
            String result = checkList(exampleList);
            System.out.println(result); // Output: single
        } catch (IllegalStateException e) {
            System.err.println(e.getMessage());
        }
    }
}
```

### Explanation:
1. **Check for Empty List**: The method `checkList` first checks if the list is empty using `list.isEmpty()`. If it is, it returns `null`.
2. **Count Elements Using Stream**: It then counts the number of elements in the list using `list.stream().count()`.
3. **Throw Exception for More Than One Element**: If the count is greater than 1, it throws an `IllegalStateException` indicating that the list contains more than one element.
4. **Return Single Element or Null**: If the list contains exactly one element, it retrieves and returns that element using `list.stream().findFirst()`. If the list is empty after the initial check, it returns `null`.

This approach ensures that the list is checked efficiently and handles different cases appropriately.

To implement a reverb effect in Kotlin using JNI (Java Native Interface), you'll need to write native code in C or C++ and then call it from your Kotlin application. Below is an example of how you can achieve this.

### Step 1: Write the Native Code (C/C++)

First, create a C file (`reverb.c`) that implements the reverb effect. This is a simple example using a basic delay-based reverb algorithm.

```c
#include <stdio.h>
#include <stdlib.h>

#define REVERB_SIZE 1024

typedef struct {
    float buffer[REVERB_SIZE];
    int head;
} Reverb;

void initReverb(Reverb *reverb) {
    for (int i = 0; i < REVERB_SIZE; i++) {
        reverb->buffer[i] = 0.0f;
    }
    reverb->head = 0;
}

float applyReverb(Reverb *reverb, float input) {
    // Simple delay-based reverb
    float output = input + reverb->buffer[(reverb->head - 1) % REVERB_SIZE];
    reverb->buffer[reverb->head] = output * 0.5f; // Adjust the decay factor
    reverb->head = (reverb->head + 1) % REVERB_SIZE;
    return output;
}
```

### Step 2: Create a Shared Library

Compile the C code into a shared library. On Linux, you can use `gcc`:

```bash
gcc -shared -o libreverb.so -fPIC reverb.c
```

On Windows, you would compile it as a DLL:

```bash
cl /LD reverb.c
```

### Step 3: Write the Kotlin Code with JNI

Now, write the Kotlin code that uses JNI to call the native functions.

```kotlin
import java.nio.ByteBuffer
import java.nio.ByteOrder

class ReverbEffect {

    private external fun initReverb(reverb: Long)
    private external fun applyReverb(reverb: Long, input: Float): Float

    companion object {
        init {
            System.loadLibrary("reverb") // Load the shared library
        }

        @JvmStatic
        fun main(args: Array<String>) {
            val reverbPtr = allocateReverb()
            try {
                val audioData = ByteBuffer.allocateDirect(16).order(ByteOrder.nativeOrder())
                audioData.putFloat(0.0f)
                audioData.putFloat(0.5f)
                audioData.putFloat(1.0f)
                audioData.putFloat(0.75f)

                audioData.rewind()

                while (audioData.hasRemaining()) {
                    val sample = audioData.getFloat()
                    val processedSample = applyReverb(reverbPtr, sample)
                    println("Processed Sample: $processedSample")
                }
            } finally {
                freeReverb(reverbPtr)
            }
        }

        private external fun allocateReverb(): Long
        private external fun freeReverb(reverb: Long)
    }
}
```

### Step 4: Generate the JNI Header File

Use the `javah` tool to generate the JNI header file:

```bash
javac ReverbEffect.kt
javah -jni ReverbEffect
```

This will generate a `ReverbEffect.h` file.

### Step 5: Implement the JNI Functions

Create a C file (`ReverbEffectJNI.c`) to implement the JNI functions:

```c
#include "ReverbEffect.h"
#include "reverb.h"

JNIEXPORT jlong JNICALL Java_ReverbEffect_allocateReverb(JNIEnv *env, jobject obj) {
    Reverb *reverb = (Reverb *)malloc(sizeof(Reverb));
    if (reverb == NULL) {
        return 0;
    }
    initReverb(reverb);
    return (jlong)reverb;
}

JNIEXPORT void JNICALL Java_ReverbEffect_freeReverb(JNIEnv *env, jobject obj, jlong reverbPtr) {
    Reverb *reverb = (Reverb *)reverbPtr;
    free(reverb);
}

JNIEXPORT void JNICALL Java_ReverbEffect_initReverb(JNIEnv *env, jobject obj, jlong reverbPtr) {
    Reverb *reverb = (Reverb *)reverbPtr;
    initReverb(reverb);
}

JNIEXPORT jfloat JNICALL Java_ReverbEffect_applyReverb(JNIEnv *env, jobject obj, jlong reverbPtr, jfloat input) {
    Reverb *reverb = (Reverb *)reverbPtr;
    return applyReverb(reverb, input);
}
```

### Step 6: Compile the JNI Code

Compile the JNI code along with the original C code into a shared library:

```bash
gcc -shared -o libreverb.so -fPIC reverb.c ReverbEffectJNI.c
```

