use std::env;
use std::io::{self, BufRead};

fn main() {
    // Get command line arguments
    let args: Vec<String> = env::args().collect();

    if args.len() < 3 {
        eprintln!("Usage: {} <pattern> [file...]", args[0]);
        return;
    }

    let pattern = &args[1];
    let files: Vec<&str> = args[2..].iter().map(|s| s.as_str()).collect();

    for file in &files {
        match open_file(file) {
            Ok(lines) => process_lines(&lines, pattern),
            Err(e) => eprintln!("Error reading {}: {}", file, e),
        }
    }
}

fn open_file(filename: &str) -> io::Result<io::Lines<io::BufReader<fs::File>>> {
    let file = fs::File::open(filename)?;
    Ok(io::BufReader::new(file).lines())
}

fn process_lines(lines: &mut dyn Iterator<Item = Result<String, io::Error>>, pattern: &str) {
    for line_result in lines {
        match line_result {
            Ok(line) => {
                if line.contains(pattern) {
                    println!("{}", line);
                }
            },
            Err(e) => eprintln!("Error processing line: {}", e),
        }
    }
}
```

