Sure, I can help you with that! Here's a simple implementation of the Connect-4 game in Python:

```python
import numpy as np

# Define the size of the board
ROWS = 6
COLUMNS = 7

# Initialize the board
board = np.zeros((ROWS, COLUMNS))

def print_board(board):
    # Print the current state of the board
    for row in range(ROWS):
        print("|", end="")
        for col in range(COLUMNS):
            if board[row][col] == 0:
                print("   |", end="")
            elif board[row][col] == 1:
                print(" X |", end="")
            else:
                print(" O |", end="")
        print()
    print("-" * (COLUMNS * 4 + 1))
    for i in range(COLUMNS):
        print(f" {i+1} ", end="")
    print()

def is_valid_location(board, col):
    # Check if the selected column is valid
    return board[ROWS - 1][col] == 0

def get_next_open_row(board, col):
    # Get the next open row in the selected column
    for r in range(ROWS):
        if board[r][col] == 0:
            return r

def drop_piece(board, row, col, piece):
    # Drop the piece into the selected row and column
    board[row][col] = piece

def winning_move(board, piece):
    # Check for a winning move
    # Check horizontal locations for win
    for c in range(COLUMNS - 3):
        for r in range(ROWS):
            if board[r][c] == piece and board[r][c+1] == piece and board[r][c+2] == piece and board[r][c+3] == piece:
                return True

    # Check vertical locations for win
    for c in range(COLUMNS):
        for r in range(ROWS - 3):
            if board[r][c] == piece and board[r+1][c] == piece and board[r+2][c] == piece and board[r+3][c] == piece:
                return True

    # Check positively sloped diagonals
    for c in range(COLUMNS - 3):
        for r in range(ROWS - 3):
            if board[r][c] == piece and board[r+1][c+1] == piece and board[r+2][c+2] == piece and board[r+3][c+3] == piece:
                return True

    # Check negatively sloped diagonals
    for c in range(COLUMNS - 3):
        for r in range(3, ROWS):
            if board[r][c] == piece and board[r-1][c+1] == piece and board[r-2][c+2] == piece and board[r-3][c+3] == piece:
                return True

def main():
    turn = 0
    game_over = False

    while not game_over:
        # Ask for Player 1 Input
        if turn % 2 == 0:
            col = int(input("Player 1 Make your Selection (1-7): ")) - 1
            if is_valid_location(board, col):
                row = get_next_open_row(board, col)
                drop_piece(board, row, col, 1)

                if winning_move(board, 1):
                    print_board(board)
                    print("PLAYER 1 WINS!!")
                    game_over = True

        # Ask for Player 2 Input
        else:
            col = int(input("Player 2 Make your Selection (1-7): ")) - 1
            if is_valid_location(board, col):
                row = get_next_open_row(board, col)
                drop_piece(board, row, col, 2)

                if winning_move(board, 2):
                    print_board(board)
                    print("PLAYER 2 WINS!!")
                    game_over = True

        print_board(board)

        turn += 1

if __name__ == "__main__":
    main()
```

This code defines a Connect-4 game where two players take turns dropping their pieces into columns on a 6x7 grid. The first player to align four of their pieces horizontally, vertically, or diagonally wins the game.

To run this program, make sure you have `numpy` installed (`pip install numpy`) and then execute the script. Enjoy playing Connect-4!

