```rust
use std::fs;
use std::io::{self, Write};
use std::path::Path;
use regex::Regex;
use reqwest::blocking::get;
use tokio::runtime::Runtime;

fn main() -> io::Result<()> {
    // Read URLs from a file
    let url_file_path = "urls.txt";
    if !Path::new(url_file_path).exists() {
        eprintln!("File not found: {}", url_file_path);
        return Ok(());
    }

    let content = fs::read_to_string(url_file_path)?;
    let lines: Vec<&str> = content.lines().collect();

    // Define a regular expression for YouTube URLs
    let re = Regex::new(r"^https?://(?:www\.)?(?:youtube\.com|youtu\.be)/").unwrap();

    // Separate YouTube URLs from other URLs
    let mut youtube_urls = Vec::new();
    let mut other_urls = Vec::new();

    for line in lines {
        if re.is_match(line) {
            youtube_urls.push(line.to_string());
        } else {
            other_urls.push(line.to_string());
        }
    }

    println!("YouTube URLs:");
    for url in &youtube_urls {
        println!("{}", url);
    }

    println!("\nOther URLs:");
    for url in &other_urls {
        println!("{}", url);
    }

    // Download YouTube URLs using yt-dlp
    let rt = Runtime::new()?;
    for url in youtube_urls {
        rt.block_on(async move {
            download_youtube_url(&url).await?;
            Ok(())
        })?;
    }

    Ok(())
}

async fn download_youtube_url(url: &str) -> Result<(), Box<dyn std::error::Error>> {
    let output_dir = "./downloads";
    let command = format!("yt-dlp -o '{}/%(title)s.%(ext)s' {}", output_dir, url);

    let status = std::process::Command::new("sh")
        .arg("-c")
        .arg(command)
        .status()
        .expect("Failed to execute command");

    if !status.success() {
        eprintln!("Failed to download video: {}", url);
    } else {
        println!("Downloaded: {}", url);
    }

    Ok(())
}
```

### Explanation:
1. **Reading URLs from File**: The program reads URLs from a file named `urls.txt`.
2. **Separating YouTube URLs**: It uses a regular expression to identify YouTube URLs.
3. **Downloading YouTube URLs**: It uses `yt-dlp` to download each identified YouTube URL. Note that this requires `yt-dlp` to be installed on your system and available in your PATH.

### Running the Program:
1. Ensure you have `yt-dlp` installed.
2. Create a file named `urls.txt` with some URLs (e.g., one or more YouTube URLs).
3. Run the program using `cargo run`.

